104	     * present; add 1 when the owner has no namesakes ({@code namesakeCount} is 0). These
105	     * pre-tenure factors are capped at 3. Level 4 is earned only by tenure — a
106	     * {@code registrationDate} more than 365 days ago. A newly created owner has zero tenure, so
107	     * it never exceeds level 3.
108	     */
109	    default Integer toMembershipLevel(Owner owner) {
110	        int level = 1;
111	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
112	        if (hasEmail) {
113	            level++;
114	        }
115	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
116	        if (unique) {
117	            level++;
118	        }
119	        // Pre-tenure factors cap at level 3; level 4 requires tenure over 365 days.
120	        level = Math.min(level, 3);
121	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
122	        if (registrationDate != null && java.time.temporal.ChronoUnit.DAYS
123	                .between(registrationDate, java.time.LocalDate.now()) > 365) {
124	            level++;
125	        }
126	        return level;
