129	    /**
130	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
131	     * last two digits of the registration-date year (e.g. {@code NSW-1A2B3C4D-M26}). Returns
132	     * null when either the customer code or registration date is absent (e.g. unmigrated seed
133	     * data).
134	     */
135	    default String toMembershipNumber(Owner owner) {
136	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
137	            return null;
138	        }
139	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
140	    }
