142	    /**
143	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the
144	     * digits contained in the {@code customerCode}. Returns null when the customer code is
145	     * absent (e.g. unmigrated seed data).
146	     */
147	    default Integer toCheckDigit(Owner owner) {
148	        String customerCode = owner.getCustomerCode();
149	        if (customerCode == null) {
150	            return null;
151	        }
152	        int sum = 0;
153	        boolean dbl = true;
154	        for (int i = customerCode.length() - 1; i >= 0; i--) {
155	            char c = customerCode.charAt(i);
156	            if (c < '0' || c > '9') {
157	                continue;
158	            }
159	            int d = c - '0';
160	            if (dbl) {
161	                d *= 2;
162	                if (d > 9) {
163	                    d -= 9;
164	                }
165	            }
166	            sum += d;
167	            dbl = !dbl;
168	        }
169	        return (10 - (sum % 10)) % 10;
170	    }
